fn solve(n: i8, m: i8) -> (i8, i8) {
    // Precondition: n >= 1, m >= 1
    debug_assert!(n >= 1 && m >= 1);

    // The second component is the smaller of the two inputs.
    let second = n.min(m);
    // The first component is the larger input minus one.
    let first = n.max(m) - 1;

    (first, second)
}

